        transliteration: 'Shashthiche divashin bhaktan aanand vartala ho,\nGheuni divatya hasti harshen gondhal ghatala ho,\nKavadi ek arpita desi haar muktaphalancha ho,\nJogava magata prasanna zhali bhaktakula ho.',
      ),
      LyricStanza(
        startTimeMs: 248178,
        devanagari: 'सप्तमीचे दिवशीं सप्तशृंगगडावरी हो ।\nतेथें तूं नांदसी भोवतें पुष्पें नानापरी हो ।\nजाईजुईशेवंती पूजा रेखियली बरवी हो ।\nभक्तसंकटी पडतां झेलूनि घेसी वरचे वरी हो ॥ उदो ॥ ७ ॥',
        transliteration: 'Saptamiche divashin saptashringagadavari ho,\nTethen tu nandasi bhovaten pushpen nanapari ho,\nJaijuishevanti pooja rekhiyali baravi ho,\nBhaktasankati padata zheluni ghesi varche vari ho.',
      ),
      LyricStanza(
        startTimeMs: 283632,
        devanagari: 'अष्टमीचे दिवशीं अष्टभुजां नारायणी हो ।\nसह्याद्रीपर्वती पाहिली उभी जगज्जननी हो ।\nमन माझें मोहिलें शरण आलों तुजलागुनी हो ।\nस्तनपान देऊनि सुखी केली अंतःकरणीं हो ॥ उदो ॥ ८ ॥',
        transliteration: 'Ashtamiche divashin ashtabhuja narayani ho,\nSahyadriparvati pahili ubhi jagajjanani ho,\nMan majhen mohilen sharan aalon tujlaguni ho,\nStanapan deuni sukhi keli antahkaranin ho.',
      ),
      LyricStanza(
        startTimeMs: 319086,
        devanagari: 'नवमीचे दिवशीं नवदिवसांचें पारणें हो ।\nसप्तशतीजप होम हवनें सद्भक्ती करूनी हो ।\nषड्रस अन्न नैवेद्यासी अर्पियली भोजनी हो ।\nआचार्यब्राह्मणां तृप्त केलें कृपेंकरूनी हो ॥ उदो ॥ ९ ॥',
        transliteration: 'Navamiche divashin navadivasanchen paarane ho,\nSaptashatijap hom havane sadbhakti karuni ho,\nShadras anna naivedyasi arpiyali bhojani ho,\nAcharyabrahmanan trupt kelen krupenkaruni ho.',
      ),
      LyricStanza(
        startTimeMs: 354540,
        devanagari: 'दशमीच्या दिवशी अंबा निघे सीमोल्लंघनी हो ।\nसिंहारूढे दारुण शस्त्रें अंबे त्वां घेऊनी हो ।\nशुंभनिशुंभादिक राक्षसा किती मारिसी रणी हो ।\nविप्रा रामदासा आश्रय दिधला तो चरणी हो ॥ उदो ॥ १० ॥',
        transliteration: 'Dashamichya divashi amba nighe seemollanghani ho,\nSinharudhe daarun shastren ambe twan gheuni ho,\nShumbhanishumbhadik rakshasa kiti marisi rani ho,\nVipra ramadasa aashray didhala to charani ho.',
      ),
    ],
  ),
