        devanagari: 'साधुवैश्यें संततिसाठीं तुजला प्रार्थियलें ।\nइच्छित पुरतां मदांध होऊनि व्रत न आचरिलें ।\nत्या पापानें संकटीं पडुनी दुःखहि भोगिलें ।\nस्मृति होऊनि आचरितां व्रत त्या तुवांचि उद्धरिलें ॥ जय ॥ ३ ॥',
        transliteration: 'Sadhuvaishyen santatisathin tujla prarthiyalen,\nIchhit purtan madandh houni vrat na aacharilen,\nTya papanen sankatin paduni dukhahi bhogilen,\nSmriti houni aacharita vrat tya tuvanchi uddharilen.',
      ),
      LyricStanza(
        startTimeMs: 142500,
        devanagari: 'प्रसाद विसरुनि पतिभेटीला कलावती गेली ।\nक्षोभ तुझा होतांचि तयाची नौका बुडाली ।\nअंगध्वजरायाची यापरि दुःखस्थिति आली ।\nमृतवार्ता शतपुत्रांची सत्वर कर्णीं परिसली ॥ जय ॥ ४ ॥',
        transliteration: 'Prasad visaruni patibhetila kalavati geli,\nKshobh tuzha hotanchi tayachi nauka budali,\nAngadhwajarayachi yapari dukhsthiti aali,\nMritvarta shataputranchi satvar karnin parisali.',
      ),
      LyricStanza(
