        devanagari: 'पुनरपि पूजुनि प्रसाद ग्रहण करितां तत्क्षणीं ।\nपतिची नौका तरली देखे कलावती नयनीं ।\nअंगध्वजरायासी पुत्र भेटति येऊनि ।\nऐसा भक्तां संकटीं पावसि तूं चक्रपाणी ॥ जय ॥ ५ ॥',
        transliteration: 'Punarapi poojuni prasad grahan karitan tatkshanin,\nPatichi nauka tarali dekhe kalavati nayanin,\nAngadhwajarayasi putra bhetati yeuni,\nAisa bhaktan sankatin pavasi tu chakrapani.',
      ),
      LyricStanza(
