        devanagari: 'अनन्यभावें पूजुनि हें व्रत जे जन आचरति ।\nइच्छित पुरविसी त्यांतें देउनि संतति संपत्ती ।\nसंहरती भवदुरितें सर्वहि बंधनें तुटती ।\nराजा रंका समान मानुनि पावसी श्रीपती ॥ जय ॥ ६ ॥',
        transliteration: 'Ananyabhaven poojuni hen vrat je jan aacharati,\nIchhit purvisi tyanten deuni santati sampatti,\nSamharati bhavaduriten sarvahi bandhanen tutati,\nRaja ranka samaan manuni pavasi shripati.',
      ),
      LyricStanza(
