        devanagari: 'ऐसा तव व्रत महिमा अपार वर्णू मी कैसा ।\nभक्तिपुरस्सर आचरती त्यां पावसि जगदीशा ।\nभक्तांचा कनवाळू कल्पद्रुम तूं सर्वेशा ।\nमोरेश्वरसुत वासुदेव तुज विनवी भवनाशा ॥ जय ॥ ७ ॥',
        transliteration: 'Aisa tav vrat mahima apaar varnoo mi kaisa,\nBhaktipurassar aacharati tyan pavasi jagadeesha,\nBhaktancha kanvaloo kalpadrum tu sarwesha,\nMoreshvarsut vasudev tuj vinavi bhavanasha.',
