        devanagari: 'अनुपम स्वरुपाची तुझी धाटी । अन्य नसे या सृष्टी ॥\nतुज सम रूप दुसरे परमेष्टी । करिता झाला कष्टी ॥\nशशीरस रसरसला वदनपुटी । दिव्य सुलोचन दृष्टी ॥\nसुवर्ण रत्नांच्या शिरी मुकुटी । लोपती रविशशी कोटी ॥\nगजमुखी तुज स्तविले हेरंबे । मंगल सकळारंभे ॥ जय जय ॥ १ ॥',
        transliteration: 'Anupam swarupaachi tujhi dhaati, anya nase ya srushti,\nTuj sam roop dusare parameshti, karita jhaala kashti,\nShashiras rasarasala vadanputi, divya sulochan drushti,\nSuvarna ratnanchya shiri mukuti, lopati ravishashi koti,\nGajmukhi tuj stavile heramba, mangal sakalaarambhe.',
      ),
      LyricStanza(
        startTimeMs: 102800,
        devanagari: 'कुमकुम चिरी शोभे मळवटी । कस्तुरी टिळक ललाटी ॥\nनासिक अति सरळ हनुवटी । रुचिरामृत रस ओठी ॥\nसमान जणू लवल्या धनुकोटी । आकर्ण लोचन भ्रुकुटी ॥\nशिरी नीट भांगवळी उफराटी । कर्नाटकची घाटी ॥\nभुजंग नीळरंगा परी शोभे । वेणी पाठीवर लोंबे ॥ जय जय ॥ २ ॥',
        transliteration: 'Kumkum chiri shobhe malavati, kastoori tilak lalaati,\nNaasik ati saral hanuvati, ruchiraamrut ras othi,\nSamaan janoo lavalya dhanukoti, aakarna lochan bhrukuti,\nShiri neet bhaangavali upharaati, karnaatakchi ghaati,\nBhujang neelranga pari shobhe, veni paathivar lombe.',
