      LyricStanza(
        startTimeMs: 154200,
        devanagari: 'कंकणे कनकाची मनगटी । दिव्य मुद्या दश बोटी ॥\nबाजूबंद जडे बाहुबटी । चर्चुनी केशर उटी ॥\nसुगंधी पुष्पांचे हार कंठी । बहु मोत्यांची दाटी ॥\nअंगी नवी चोळी जरीकाठी । पीत पितांबर तगटी ॥\nपैंजण पदकमळी अति शोभे । भ्रमर धावती लोभे ॥ जय जय ॥ ३ ॥',
        transliteration: 'Kankane kanakaachi managati, divya mudya dash boti,\nBaajooband jade baahubati, charchuni keshar uti,\nSugandhi pushpaanche haar kanthi, bahu motyaanchi daati,\nAngi navi choli jarikaathi, peet pitaambar tagati,\nPainjan padkamali ati shobhe, bhramar dhaavati lobhe.',
      ),
      LyricStanza(
        startTimeMs: 205600,
        devanagari: 'साक्षप तू क्षितिच्या तळवटी । तूचि स्वये जगजेठी ॥\nओवाळीत आरती दिपताटी । घेऊनी कर संपुष्टी ॥\nकरुणामृत हृदये संकटी । धावसी भक्तांसाठी ॥\nविष्णूदास सदा बहुकष्टी । देशील जरी नीजभेटी ॥\nतरी मग काय उणे या लाभे । धाव पाव अविलंबे ॥ जय जय ॥ ४ ॥',
        transliteration: 'Saakshap tu kshitichya talavati, tuchi swaye jagjethi,\nOvaalit aarati dipataati, gheuni kar sampushti,\nKarunaamrut hrudaye sankati, dhaavasi bhaktaansaathi,\nVishnudaas sada bahukashti, deshil jari nijbheti,\nTari mag kaay une ya laabhe, dhaav paav avilambe.',
      ),
    ],
