        transliteration: 'Nirgun sagunaakaaram samhrutbhoobhaaram,\nMurahar nandakumaaram munijan sukhakaaram,\nVrundaavan sanchaaram kaustubh manihaaram,\nKarunaapaaraavaaram govardhan dhaaram.',
