        transliteration: 'Kunchit kuntalneelam sharadindubhavadanam,\nManigan mandit kundal shobhit shrutiyugalam,\nVikasit pankajnayanam vilasit bhrooyugalam,\nBimbaadhar matisundar naasaamanilolam.',
