        transliteration: 'Kambugreevam kaustubh manikanthaabharanam,\nShreevatsaankitdeham lambitvanmaalam,\nBhooshit bhujvaryugalam kartal dhrutvenum,\nTrivaleeshobhitmadhyam kardhrut navaneetam.',
