        transliteration: 'Muraleevaadan leelaasaptaswarageetam,\nJalachar vanachar khecharranjan sangeetam,\nStambhityamunaatoyam paramaadbhutcharitam,\nGopeechitta vinodankaaram shreekaantam.',
      ),
      LyricStanza(
