        devanagari: 'रासक्रीडा मंडल वेष्टितव्रज ललनं ।\nमध्ये तांडव नृत्य कोमल पदयुगलं ॥\nकुसुमाकार विरंजित मंदस्मित वदनं ।\nकालियफणी वरदलनं यक्षेश्वरहन्नं ॥ ५ ॥',
        transliteration: 'Raasakreeda mandal veshtitvraj lalanam,\nMadhye taandav nrutya komal padyugalam,\nKusumaakaar viranjit mandasmit vadanam,\nKaaliyaphanee varadalanam yaksheshwarahannam.',
