        devanagari: 'मणि मण्डित मध्यम पीताम्बर वसनं ।\nमंजुल नूपुर शिञ्जित विलसत्पदयुगलं ॥\nगोगोपीपरिवेष्टित यमुनातट संस्थं ।\nव्यासाभयदं सुखदं भुवनत्रयपालं ॥\nजय देव जय देव ॥ ६ ॥',
