        devanagari: 'आवडी गंगाजळे देवा न्हाणीलें ।\nभक्तीचें भूषण प्रेमे सुगंध अर्पिले ॥ १ ॥\nअहं हा धूप जाळूं श्रीहरीपुढे ।\nजंव जंव धूप जळे तंव तंव देवा आवडे ॥ २ ॥\nरमावल्लभदासे अहं धूप जाळीला ।\nएकारतीचा मग प्रारंभ केला ॥ ३ ॥',
        transliteration: 'Aavadi gangaajale deva nhaanilen,\nBhaktichen bhooshan preme sugandh arpile,\nAham ha dhoop jaaloon shreeharipudhe,\nJanv janv dhoop jale tanv tanv deva aavade,\nRamaavallabhdaase aham dhoop jaalila,\nEkaaratiicha mag praarambh kela.',
